INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "李景隆", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "曹国公。本纪记其在建文元年继耿炳文后为征虏大将军。", "biography": null, "status": "draft", "id": "74bfbb9a-13ef-5b0a-8ce8-2e9f902907af"}, {"name": "铁铉", "aliases": ["鐵鉉"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文2年（年号对照1400年）十二月，铁铉获任兵部尚书，督理军务。", "biography": null, "status": "draft", "id": "c762b1dc-9ad1-5d54-95f1-1a34c8da3202"}, {"name": "盛庸", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明初将领。本纪记其为都督，参与守卫济南。", "biography": null, "status": "draft", "id": "30198cca-1b25-5099-9bd8-021538a90b39"}, {"name": "朱允炆", "aliases": ["明惠帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明惠帝。洪武31年（年号对照1398年），本表记录了朱允炆的活动。", "biography": null, "status": "draft", "id": "76ea9485-acac-508c-a6ae-e2532462c03e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "燕军由蔚州进攻大同，李景隆率军赴援", "description": "燕军攻下蔚州后进攻大同。李景隆从德州率军增援，燕军撤回北平。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9ce71773-abff-5e1d-94e6-caec1072b757"}, {"title": "交战前李景隆进兵河间，朱棣进驻苏家桥", "description": "李景隆进军河间，约郭英、吴杰和平安在白沟河会师。朱棣于乙卯驻营苏家桥。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5c17baf5-978c-52df-b15a-acd62b0667a5"}, {"title": "李景隆在白沟河首次交战击败燕军", "description": "李景隆与燕军在白沟河交战，朝廷军队此日获胜。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年四月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2accd96e-c3cb-506f-9442-61458ba45ab1"}, {"title": "白沟河再战李景隆败退", "description": "次日双方再战，李景隆军失利，都督瞿能、越巂侯俞渊、指挥滕聚等阵亡，李景隆奔往德州。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年四月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7225511e-6045-5978-a464-763fb146ac35"}, {"title": "李景隆退往济南，燕军攻占德州", "description": "李景隆退往济南。燕军攻占德州，继续进攻济南。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年五月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dc19184a-4150-58c6-840c-3f5b07b28e0d"}, {"title": "李景隆在济南城下败退，铁铉与盛庸守城", "description": "李景隆在济南城下战败后南撤。参政铁铉与都督盛庸竭力抵御燕军。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年五月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2bb0f955-fa59-54e7-a942-318192365828"}, {"title": "盛庸铁铉击败燕军，济南解围", "description": "盛庸与铁铉击败燕军，济南解围，朝廷军队收复德州。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年八月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "77e9ba24-6906-5350-b018-aaa7fdaf9ddf"}, {"title": "盛庸任平燕将军，官军分屯德州等地", "description": "朝廷任命盛庸为平燕将军，陈晖和平安为副将。盛庸屯驻德州，平安和吴杰屯驻定州，徐凯屯驻沧州。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e7e96362-1c95-5315-a429-0ca10919706e"}, {"title": "燕军向南进兵沧州方向", "description": "徐凯正在营筑沧州时，朱棣假称出兵攻辽东。燕军到通州后沿河向南，经直沽日夜行军。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1640c2f0-7515-5607-b757-72a797b495f2"}, {"title": "燕军袭击沧州并俘获徐凯", "description": "燕军袭击沧州，徐凯被俘。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年十月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "78851b24-29a4-5beb-9f54-d5145fd6ea88"}, {"title": "燕军渡河过德州后击败来军", "description": "燕军渡河经过德州。盛庸派兵来袭，燕军击败来军。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "504f5e1d-9edc-514b-89ff-86f78f400d9b"}, {"title": "燕军抵达临清", "description": "本纪记燕军于十一月壬申到达临清。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年十一月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "502a6f59-6916-5e61-9cbc-d9b18a65f4e7"}, {"title": "燕军在滑口袭破孙霖所部", "description": "燕军在滑口突袭盛庸麾下孙霖所部并击败对方。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年十二月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ae8e5809-e441-5a3e-bd49-f5be4d59d150"}, {"title": "盛庸在东昌击败燕军，张玉阵亡", "description": "盛庸率军击败燕军，燕军将领张玉在此役被杀。", "start_year": 1401, "end_year": 1401, "time_original": "建文二年十二月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fd72bba0-e456-56ce-bdb8-4f4e839d20ee"}, {"title": "吴杰平安在深州拦击燕军失利", "description": "吴杰、平安在深州拦击燕军，交战失利。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年正月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dfe428ee-5496-52f5-acb8-4ba292e97b74"}, {"title": "朱棣再次率军南下", "description": "本纪记载，朱棣于二月乙巳再次率军南下。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年二月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1cbde4c2-4968-5e50-a374-60a103c16e33"}, {"title": "盛庸在夹河击败燕军", "description": "盛庸率军在夹河击败燕军，燕将谭渊被杀。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年三月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aaf81159-ab86-57d7-9573-d59993ec919b"}, {"title": "盛庸再次失利后退往德州", "description": "本纪记载，盛庸所部于壬午再次交战，战败后退往德州。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年三月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ded37718-ffa3-5579-95e9-7d99cda06225"}, {"title": "吴杰平安在藁城失利后退守真定", "description": "吴杰、平安在藁城与燕军交战失利，退守真定。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年闰三月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c245b9f9-45f9-5e24-ad1b-e8bf368b5d4f"}, {"title": "朱棣上书请停兵，朝廷派薛嵓答复", "description": "朱棣上书请朝廷召还诸将并停止作战。朝廷派大理少卿薛嵓答复。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年闰三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2e6a9a8-421c-5904-8782-9521640dd3de"}, {"title": "盛庸试图截断燕军运粮路线", "description": "盛庸出兵试图截断燕军运粮路线，未能成功。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年五月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ea280acd-cd7e-5c5b-bc62-fd36b7a2a9af"}, {"title": "朱棣再次上书，朝廷扣押其使者", "description": "朱棣再次派使者上书朝廷，朝廷将来使关押入狱。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "29ad4837-42b3-5753-9dfb-912090df04e9"}, {"title": "燕将李远在沛县烧毁运粮船", "description": "燕军将领李远进袭沛县，烧毁运粮船。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年六月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "36540de1-fe2c-566e-b0f9-9d192faa1d09"}, {"title": "燕军进掠彰德", "description": "本纪记载，燕军在七月己丑进掠彰德。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年七月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0b756b50-92b8-5bc2-a36a-8d4593f85588"}, {"title": "燕军招降林县", "description": "本纪记燕军于七月丙申招降林县。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年七月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "58e0a274-9ec3-59c1-ac26-77d2c3a8eea3"}, {"title": "平安从真定出兵攻北平", "description": "平安于七月丁酉从真定率军攻打北平。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年七月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0474dd05-cc6f-5b17-bd70-f9d0b01718d6"}, {"title": "房昭经紫荆关进抵易州西水寨", "description": "大同守将房昭率军经紫荆关赶往保定，驻扎在易州西水寨。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年七月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "46d1d1fc-e820-5203-9be9-0a63d3aa7aca"}, {"title": "真定援军在齐眉山对燕军作战失利", "description": "真定诸将派兵增援房昭，援军与燕王所部在齐眉山交战失利。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年十月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f864af6a-8596-51e0-81c4-296b13885e4e"}, {"title": "燕军返回北平", "description": "本纪记燕军在十月己卯返回北平。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年十月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5a5f6ed0-5468-59eb-8066-aa35d9fc6602"}, {"title": "朱棣作文祭奠双方阵亡将士", "description": "朱棣亲自写祭文，祭奠南北两军的阵亡将士。", "start_year": 1402, "end_year": 1402, "time_original": "建文三年十一月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3a347440-d876-5380-a06d-55151e5666b0"}, {"title": "朱棣在十二月再次发兵", "description": "《成祖本纪》记朱棣在十二月丙寅再次出兵。", "start_year": 1402, "end_year": 1402, "time_original": "建文三年十二月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "899110bf-1a3d-5b2c-b602-7517098e8d4c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

