INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "朱棣所部攻占蔚州。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000953；建文二年正月丙寅", "note": "原文：二年春正月丙寅，克蔚州。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "97be5291-5521-5abd-b049-17d2bfb94c58", "subject_id": "dd806a37-77e8-5244-96e9-4d71db81b600", "source_id": "2d7b378a-d88b-5173-abd4-fef222ecf365"}, {"subject_table": "event", "field_path": "description", "claim_text": "《成祖本纪》将燕军攻占蔚州系于建文二年正月丙寅。卷四在二月条合记攻蔚州、向大同进军。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000953；建文二年正月丙寅", "note": "原文：二年春正月丙寅，克蔚州。；核对说明：卷四、卷五将同一行动系于不同月份或干支。保存本卷原词和各自定位，沿用既有事件编号。", "status": "draft", "id": "db74d487-a1ec-5af9-b725-07d20f3bc0a9", "subject_id": "9ce71773-abff-5e1d-94e6-caec1072b757", "source_id": "2d7b378a-d88b-5173-abd4-fef222ecf365"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历建文二年正月丙寅。DDBC历表换算所据为1400-02-03至1400-02-03，据此核对公元发生年份。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000953；建文二年正月丙寅", "note": "原文：二年春正月丙寅，克蔚州。；核对说明：卷四、卷五将同一行动系于不同月份或干支。保存本卷原词和各自定位，沿用既有事件编号。", "status": "draft", "id": "d8d5823d-889f-5152-aec4-b491de1af3c4", "subject_id": "9ce71773-abff-5e1d-94e6-caec1072b757", "source_id": "2d7b378a-d88b-5173-abd4-fef222ecf365"}, {"subject_table": "event", "field_path": "description", "claim_text": "卷五记朱棣在二月癸丑到大同，李景隆经紫荆关来援。朱棣已经转军居庸，李景隆军多人冻饿死亡，未遇燕军而回。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000954；建文二年二月癸丑起叙", "note": "原文：二月癸丑，至大同。景隆果由紫荊關來援。王已旋軍居庸，景隆兵多凍餒死者，不見敵而還。；核对说明：按同一段大同战事沿用卷四事件编号，保留方位及本卷的明确日期。", "status": "draft", "id": "5237a970-1395-5b03-9dea-4ca3c0d140ec", "subject_id": "9ce71773-abff-5e1d-94e6-caec1072b757", "source_id": "6cb6e801-ec6a-5e19-871c-11a4cea00dd9"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "所部攻占蔚州", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000953；建文二年正月丙寅", "note": "原文：二年春正月丙寅，克蔚州。；核对说明：只采用本段明确参与者和行动角色，既有连接按稳定编号复用。", "status": "draft", "id": "d73ae64c-7ff1-5be9-ae6e-172a3ec2f7fa", "subject_id": "fbea8d1f-9a4c-546c-a409-a6c324577283", "source_id": "2d7b378a-d88b-5173-abd4-fef222ecf365"}, {"subject_table": "person", "field_path": "description", "claim_text": "李景隆进军河间安排会师。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000955；建文二年四月", "note": "原文：夏四月，景隆進兵河間，與郭英、吳傑、平安期會白溝河。乙卯，王營蘇家橋。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "e0abf857-b744-5ea0-be51-d07f7fccf883", "subject_id": "74bfbb9a-13ef-5b0a-8ce8-2e9f902907af", "source_id": "3d173367-9600-556d-a16b-ef3656b69a19"}, {"subject_table": "event", "field_path": "description", "claim_text": "李景隆进军河间，约郭英、吴杰和平安在白沟河会师。朱棣于乙卯驻营苏家桥。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000955；建文二年四月", "note": "原文：夏四月，景隆進兵河間，與郭英、吳傑、平安期會白溝河。乙卯，王營蘇家橋。；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "2ad736a0-66ba-550e-9009-f728eef8acad", "subject_id": "5c17baf5-978c-52df-b15a-acd62b0667a5", "source_id": "3d173367-9600-556d-a16b-ef3656b69a19"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历建文二年四月。DDBC历表换算所据为1400-05-04至1400-06-01，据此核对公元发生年份。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000955；建文二年四月", "note": "原文：夏四月，景隆進兵河間，與郭英、吳傑、平安期會白溝河。乙卯，王營蘇家橋。；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "66a8cedd-2064-5db9-99fa-c76e6c1d31e5", "subject_id": "5c17baf5-978c-52df-b15a-acd62b0667a5", "source_id": "3d173367-9600-556d-a16b-ef3656b69a19"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "进军河间安排会师", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000955；建文二年四月", "note": "原文：夏四月，景隆進兵河間，與郭英、吳傑、平安期會白溝河。乙卯，王營蘇家橋。；核对说明：只采用本段明确参与者和行动角色，既有连接按稳定编号复用。", "status": "draft", "id": "27baecca-aaa9-57c6-83e5-da4363b559d1", "subject_id": "6d6a828e-e679-5b07-843d-1a4f51941150", "source_id": "3d173367-9600-556d-a16b-ef3656b69a19"}, {"subject_table": "pers